-- =============================================================
-- 云栖茶饮 · 演示数据（最近 30 天的用户与订单）
-- 前置：已执行 cloud_tea_schema.sql + cloud_tea_seed.sql
--
-- 时间全部用 CURDATE() 的相对表达式，因此任何时候重跑这个脚本，
-- 数据都落在「最近 30 天」，统计报表不会因为脚本变旧而空掉。
--
-- 注意：会清空并重建 user / address_book / orders / order_detail / shopping_cart，
--       菜单（category / drink / drink_spec / combo / combo_drink）与员工不受影响。
-- =============================================================

USE cloud_tea;

DELETE FROM order_detail;
DELETE FROM orders;
DELETE FROM shopping_cart;
DELETE FROM address_book;
DELETE FROM user;

ALTER TABLE user AUTO_INCREMENT = 1;
ALTER TABLE address_book AUTO_INCREMENT = 1;
ALTER TABLE orders AUTO_INCREMENT = 1;
ALTER TABLE order_detail AUTO_INCREMENT = 1;

